       KZWr P 10; KZDisj P 10 (DT + 4) (4 * 2^tl); KZDisj P 10 0x7fff8000 17592186044416;
       KZRange DT 0x5ed000 (2^47 - 8388608); KZRange P 0x5ed000 (2^47 - 8388608)]
      [(DT + 4, 4 * 2^tl)]
      [(DT + 4, 4 * 2^tl); (P, 10)]
      [(DT + 4, 4 * 2^tl); (P, 10)];
    try (lazymatch goal with |- evtF _ _ _ _ => fail | _ => unfold KXGoM.apart in *; lia end).

